SELECT CASE WHEN pressure >= 1025 THEN 'HIGH' ELSE 'LOW' END AS pressure_tier, CASE WHEN status_bits >= 13 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_bits_tier, AVG(temp_c) FILTER (WHERE device_code = 'DV-04') AS dv_04_avg_temp_c, CORR(status_bits, pressure) AS corr_status_bits_pressure FROM device_readings GROUP BY CASE WHEN pressure >= 1025 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN status_bits >= 13 THEN 'PREMIUM' ELSE 'STANDARD' END;
